package org.asundr;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Offer at Price",
	description = "SHIFT-right click an item to offer a matching quantity for a provided price. Also displays current price overlay.",
	tags = {"trade", "auto", "calc", "calculate", "value", "scam", "protection"}
)
public class OfferAtPricePlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OfferAtPriceConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private EventBus eventBus;
	@Inject private KeyManager keyManager;
	@Inject private ItemManager itemManager;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private ChatboxPanelManager chatboxPanelManager;
	@Inject private Notifier notifier;

	private OfferManager offerManager;

	@Override
	protected void startUp() throws Exception
	{
		PriceUtils.initialize(client, itemManager, notifier, chatMessageManager, chatboxPanelManager);
		offerManager = new OfferManager(config, client, clientThread, eventBus, overlayManager, keyManager, itemManager);
	}

	@Override
	protected void shutDown() throws Exception
	{
		offerManager.shutdown();
	}

	@Provides
	OfferAtPriceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OfferAtPriceConfig.class);
	}
}

package org.asundr;

import com.google.common.collect.ImmutableSet;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.Text;

import java.awt.*;
import java.util.HashMap;
import java.util.Set;

public class OverlayLastMessage extends OverlayPanel
{
    private static final int OFFSET_TRADE_OFFER = -10;
    private static final int OFFSET_TRADE_CONFIRM = -25;
    private static final String TEMPLATE_MESSAGE = "%s: %s";
    private static final Set<ChatMessageType> VALID_CHAT_TYPES = ImmutableSet.of(
            ChatMessageType.PUBLICCHAT,
            ChatMessageType.FRIENDSCHAT,
            ChatMessageType.CLAN_CHAT,
            ChatMessageType.PRIVATECHAT,
            ChatMessageType.MODCHAT,
            ChatMessageType.MODPRIVATECHAT,
            ChatMessageType.CLAN_GUEST_CHAT
    );
    private static OfferAtPriceConfig config;
    private static final HashMap<String, MessageNode> lastMessages = new HashMap<>();

    OverlayLastMessage(OfferAtPriceConfig config)
    {
        OverlayLastMessage.config = config;

        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPreferredColor(Color.GREEN);
        setBounds(new Rectangle(100,100));
    }

    @Subscribe
    private void onChatMessage(ChatMessage evt)
    {
        final String jagexName = Text.toJagexName(Text.removeTags(evt.getMessageNode().getName()));
        if (!VALID_CHAT_TYPES.contains(evt.getType()))
        {
            return;
        }
        lastMessages.put(jagexName, evt.getMessageNode());
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final String playerName = OfferManager.getOfferInfo().playerName;
        if (OfferManager.getOfferInfo().playerName == null)
        {
            return null;
        }
        final String jagexName = Text.toJagexName(playerName);
        if (!config.showLastChat() || !OfferManager.isTrading() || !lastMessages.containsKey(jagexName))
        {
            return null;
        }
        final String lastMessage = String.format(TEMPLATE_MESSAGE, playerName, Text.removeTags(lastMessages.get(jagexName).getValue()));
        panelComponent.getChildren().add(TitleComponent.builder()
                .text(lastMessage)
                .color(config.colorOfLastChatOverlay())
                .build());
        panelComponent.setPreferredSize(new Dimension(
                graphics.getFontMetrics().stringWidth(lastMessage) + 10,
                40));
        final Rectangle rect = OfferManager.getTradeMenuLocation();
        final int yOffset = OfferManager.getTradeState() == OfferManager.TradeState.TRADE_OFFER ? OFFSET_TRADE_OFFER : OFFSET_TRADE_CONFIRM;
        setPreferredLocation(new java.awt.Point((int)rect.getX() + rect.width/2 - getBounds().width/2, yOffset + (int)rect.getY()));
        return super.render(graphics);
    }
}

