import java.awt.*;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PriceUtils
{
    public static final int TRADEOTHER = InventoryID.TRADEOFFER | 0x8000;
    public static final String REGEX_VALID_PRICE = "^-?(?:\\d+(?:\\.\\d+)?|\\.?\\d+)[kmb]$";
    public static final String TEXT_PLUGIN_PREFIX = "Offer at Price";
    private static final String TEXT_WARNING_BOTH_CURRENCY = "You must offer items for coins";
    private static final String TEXT_WARNING_BOTH_ITEMS = "You must offer coins for items";
    private static final String TEXT_WARNING_OTHER_EMPTY = "Other player must offer before you can offer at price";
    private static final String TEXT_WARNING_SINGLE_ITEM_TYPE = "You can only offer at price for a single type of item";
    private static final Color COLOR_PLUGIN_PREFIX = new Color(0, 100, 0);

    private static Client client;
    private static ItemManager itemManager;
    private static Notifier notifier;
    private static ChatMessageManager chatMessageManager;
    private static ChatboxPanelManager chatboxPanelManager;

    // Caches a map of original item IDs to the ID of their noted variant
    private static final HashMap<Integer, Integer> notedIdMap = new HashMap<>();

    public static void initialize(final Client client, final ItemManager itemManager, final Notifier notifier, final ChatMessageManager chatMessageManager, final ChatboxPanelManager chatboxPanelManager)
    {
        PriceUtils.client = client;
        PriceUtils.itemManager = itemManager;
        PriceUtils.notifier = notifier;
        PriceUtils.chatMessageManager = chatMessageManager;
        PriceUtils.chatboxPanelManager = chatboxPanelManager;
    }

    // Removes html tags from string
    public static String sanitizeWidgetText(final String s)
    {
        return s.replaceAll("<[^>]*>", "").trim();
    }

    // Returns true if the passed string can be parsed as a long
    public static boolean isLongNumber(final String s)
    {
        try { Long.parseLong(s); } catch (Exception e) { return false; } return true;
    }

    public static boolean isIntegerNumber(final String s)
    {
        try { Integer.parseInt(s); } catch (Exception e) { return false; } return true;
    }

    // Returns true if the passed string is a whole number or can be converted into one
    public static boolean isValidPrice(final String s)
    {
        return s != null && (isLongNumber(s) || s.matches(REGEX_VALID_PRICE));
    }

    // Returns true if passed item id is for coins or platinum chips
    public static boolean isCurrency(final int itemId)
    {
        return itemId == ItemID.COINS || itemId == ItemID.PLATINUM;
    }

    // Returns the total number of an item with the passed ID. Noted items are treated as their un-noted versions.
    public static long getQuantity(final int inventoryId, final int itemId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null)
        {
            return 0;
        }
        long total = 0L;
        final long originalID = notedIdMap.getOrDefault(itemId, itemId);
        for (final Item item : container.getItems())
        {
            if (item == null || item.getId() == -1)
            {
                continue;
            }
            if (originalID == notedIdMap.getOrDefault(item.getId(), item.getId()))
            {
                total += item.getQuantity();
            }
        }
        return total;
    }

    // Returns true if the container has no items
    public static boolean isContainerEmpty(final int inventoryId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        return container == null || container.count() == 0;
    }

    // Returns the ID for the first item in the inventory, or -1 if none found
    public static int getFirstItem(final int inventoryId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null || container.count() == 0)
        {
            return -1;
        }
        return Arrays.stream(container.getItems()).filter(item -> item != null && item.getId() != -1).findFirst().get().getId();
    }

    // Returns true if every item in the inventory has the same ID. Noted items are treated as their un-noted versions.
    public static boolean hasOneTypeOfItem(final int inventoryId)
    {
        if (isCurrencyOnly(inventoryId))
        {
            return true;
        }
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null)
        {
            return false;
        }
        int id = -1;
        for (final Item item : container.getItems())
        {
            if (item == null || item.getId() == -1)
            {
                continue;
            }
            if (id == -1)
            {
                id = notedIdMap.getOrDefault(item.getId(), item.getId());
            }
            else if (id != notedIdMap.getOrDefault(item.getId(), item.getId()))
            {
                return false;
            }
        }
        return id != -1;
    }

    // Returns true if the inventory only contains coins and platinum. Returns false if empty.
    public static boolean isCurrencyOnly(final int inventoryId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null || container.count() == 0)
        {
            return false;
        }
        for (final Item item : container.getItems())
        {
            if (item == null || item.getId() == -1)
            {
                continue;
            }
            if (!isCurrency(item.getId()))
            {
                return false;
            }
        }
        return true;
    }

    // Returns the total value of all coins and platinum chips in the inventory.
    public static long getTotalCurrencyValue(final int inventoryId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null || container.count() == 0)
        {
            return 0L;
        }
        long sum = 0;
        for (final Item item : container.getItems())
        {
            if (item == null)
            {
                continue;
            }
            switch (item.getId())
            {
                case ItemID.COINS:
                    sum +=  item.getQuantity(); break;
                case ItemID.PLATINUM:
                    sum += (item.getQuantity() * 1000L); break;
            }
        }
        return sum;
    }

    // Analyzes the trade and returns whether the players is selling one type of item, buying one type of item or is more complex (INVALID)
    // showReason - if true, will show messages in the chat explaining why Offer-at-price option isn't visible
    public static TradeType getOfferType(final int itemId, final boolean showReason)
    {
        final String reason;
        final boolean offerCurrency = isCurrency(itemId);
        if (isContainerEmpty(TRADEOTHER))
        {
            reason = TEXT_WARNING_OTHER_EMPTY;
        }
        else if (offerCurrency == isCurrencyOnly(TRADEOTHER)) // trading coins for coins or items for items
        {
            reason = offerCurrency ? TEXT_WARNING_BOTH_CURRENCY : TEXT_WARNING_BOTH_ITEMS;
        }
        else if (offerCurrency && !hasOneTypeOfItem(TRADEOTHER))
        {
            reason = TEXT_WARNING_SINGLE_ITEM_TYPE;
        }
        else
        {
            return offerCurrency ? TradeType.BUYING : TradeType.SELLING;
        }
        if (showReason && !reason.isBlank())
        {
            PriceUtils.chatMessage(false, reason, true);
        }
        return TradeType.INVALID;
    }

    // Given a widget, tries to find a valid item ID in it or its child widgets
    public static int getItemIdFromWidget(Widget w)
    {
        int itemId = w.getItemId();
        if (itemId == -1 && w.getChildren() != null)
        {
            for (final Widget child : w.getChildren())
            {
                if (child.getItemId() != -1)
                {
                    return child.getItemId();
                }
            }
        }
        return itemId;
    }

    // Returns a string matching the passed pattern if that pattern finds a match in the widget represented by the group and child IDs
    public static String extractPatternFromWidget(int groupId, int childId, final Pattern p)
    {
        final Widget tradingWithWidget = client.getWidget(groupId, childId);
        if (tradingWithWidget == null)
        {
            return null;
        }
        final String widgetText = Text.removeTags(tradingWithWidget.getText()).trim();
        final Matcher m = p.matcher(widgetText);
        if (m.find())
        {
            return m.group(1);
        }
        return null;
    }

    // Caches the relationship between noted and un-noted IDs for any new items from the passed inventory
    public static void updateNotedIds(final int inventoryId)
    {
        final ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null || container.count() == 0)
        {
            return;
        }
        for (final Item item : container.getItems())
        {
            if (item == null || item.getId() == -1 || notedIdMap.containsKey(item.getId()))
            {
                continue;
            }
            var comp = itemManager.getItemComposition(item.getId());
            notedIdMap.put(item.getId(), comp.getNote() == -1 ? item.getId() : comp.getLinkedNoteId());
        }
    }

    public static void promptString(final String prompt, final String initialText, final Consumer<String> response)
    {
        chatboxPanelManager.openTextInput(prompt)
                .value(Strings.nullToEmpty(initialText))
                .onDone((content) ->
                {
                    if (content == null)
                    {
                        return;
                    }
                    content = Text.removeTags(content).trim();
                    response.accept(content);
                }).build();
    }

    private static int[] findIndexes(String s, String match)
    {
        final ArrayList<Integer> indexes = new ArrayList<>();
        int index = -2;
        while ((index = s.indexOf(match, index+2)) != -1)
        {
            indexes.add((index));
        }
        return indexes.stream().mapToInt(i -> i).toArray();
    }

    static void chatMessageWithHighlighting(final boolean notify, boolean pluginPrefix, final String format, Object... args)
    {
        final ChatMessageBuilder builder = new ChatMessageBuilder();
        if (pluginPrefix)
        {
            builder.append("[").append(COLOR_PLUGIN_PREFIX, TEXT_PLUGIN_PREFIX).append("] ");
        }
        final int[] indexes = findIndexes(format, "%s");
        assert indexes.length == args.length : String.format("Expecting %s args but received %s", indexes.length, args.length);
        int lastIndex = 0;
        for (int i=0; i <indexes.length; ++i)
        {
           builder.append(format.substring(lastIndex, indexes[i])).append(Color.blue, ((String)args[i]));
           lastIndex = indexes[i] + 2;
        }
        if (format.length() > lastIndex)
        {
            builder.append(format.substring(lastIndex));
        }
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.GAMEMESSAGE)
                .runeLiteFormattedMessage(builder.build())
                .build());
        if (notify)
        {
            notifier.notify(Text.removeTags(String.format(format, args)));
        }
    }

    public static void chatMessage(final boolean notify, final String message, boolean pluginPrefix)
    {
        final ChatMessageBuilder builder = new ChatMessageBuilder();
        if (pluginPrefix)
        {
            builder.append("[").append(COLOR_PLUGIN_PREFIX, TEXT_PLUGIN_PREFIX).append("] ");
        }
        builder.append(message);
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.GAMEMESSAGE)
                .runeLiteFormattedMessage(builder.build())
                .build());
        if (notify)
        {
            notifier.notify(Text.removeTags(message));
        }
    }

    // Adapted from Decimal Prices
    private static final BigDecimal ONE_THOUSAND = new BigDecimal(1_000);
    private static final BigDecimal ONE_MILLION = new BigDecimal(1_000_000);
    private static final BigDecimal ONE_BILLION = new BigDecimal(1_000_000_000);
    private static final BigDecimal MAX = new BigDecimal(2_147_483_647);
    public static String transformDecimalPrice(String inputPrice)
    {
        final String decimalPrice = inputPrice.trim().toLowerCase().replace(',', '.');
        if (decimalPrice.isEmpty())
        {
            return inputPrice;
        }
        // if passed string isn't a decimal return it as-is
        if (!decimalPrice.matches(REGEX_VALID_PRICE))
        {
            return inputPrice;
        }
        int priceStringLen = decimalPrice.length();
        // get the unit from the end of string, k (thousands), m (millions) or b (billions)
        char unit = decimalPrice.charAt(priceStringLen - 1);
        final boolean isNegative = decimalPrice.charAt(0) == '-';
        // get the number xx.xx without the unit and parse as a BigDecimal (for precision)
        BigDecimal amount = new BigDecimal(decimalPrice.substring(isNegative ? 1 : 0, priceStringLen - 1));
        // multiply the number and the unit
        BigDecimal product;
        switch (unit)
        {
            case 'k':
                product = amount.multiply(ONE_THOUSAND);
                break;
            case 'm':
                product = amount.multiply(ONE_MILLION);
                break;
            case 'b':
                product = amount.multiply(ONE_BILLION);
                break;
            default:
                product = BigDecimal.ZERO;
                break;
        }
        // bound result to maximum allowable price
        if (product.compareTo(MAX) > 0) {
            product = MAX;
        }
        // cast the BigDecimal to an int, truncating anything after the decimal in the process
        int truncatedProduct = product.intValue();
        return (isNegative ? "-" : "") + String.valueOf(truncatedProduct);
    }
}

